"""Visit records."""


class Visit:
    def __init__(self, page, minutes):
        self.page = page
        self.minutes = minutes

    def __repr__(self):
        return "Visit(%r, %r)" % (self.page, self.minutes)


ROWS = [('home', 44), ('docs', 28), ('shop', 38), ('home', 34), ('blog', 43)]


def load_visits():
    """Yield the stored visits one at a time."""
    for page, minutes in ROWS:
        yield Visit(page, minutes)


def feed_visits():
    """Endless feed of visits: repeats the stored rows for ever."""
    while True:
        for page, minutes in ROWS:
            yield Visit(page, minutes)
